package ama.api;
import ama.contract.IdentityContracts.*;import ama.contract.MinutesContracts;import ama.contract.TaskContracts.*;import ama.minutes.ControlledMinutesDataSource;import ama.storage.*;import ama.transcript.*;
import java.util.*;import java.nio.file.*;import java.sql.*;import java.lang.reflect.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.AbstractDataSource;import org.springframework.core.env.*;import org.springframework.transaction.support.TransactionSynchronizationManager;import com.fasterxml.jackson.databind.ObjectMapper;
/** Real factory/queue/preparer with entry/exit-only instrumentation; original bodies run unchanged. No handler wrapper retries or SQL leases. */
public final class LocalCoverageBudgetCheck {
 static void check(boolean value,String message){if(!value)throw new IllegalStateException(message);}
 static final class Source extends AbstractDataSource {
  final DataSource delegate;final String meeting;final Thread thread=Thread.currentThread();volatile boolean armed;Callable<Boolean> renewal;int renewals;String mode="CUMULATIVE";int discoveries;long started;final List<Long> pauses=new ArrayList<>();
  Source(DataSource source,String meeting){delegate=source;this.meeting=meeting;}
  static Object invoke(Object o,Method m,Object[] a)throws Throwable{try{return m.invoke(o,a);}catch(InvocationTargetException failure){throw failure.getCause();}}
  Object proxy(Object o,Class<?> t,InvocationHandler h){return Proxy.newProxyInstance(t.getClassLoader(),new Class[]{t},h);}
  Connection wrap(Connection actual){return(Connection)proxy(actual,Connection.class,(p,m,a)->{
   if(m.getName().equals("equals"))return p==a[0];if(m.getName().equals("hashCode"))return System.identityHashCode(p);Object value=invoke(actual,m,a);
   if(m.getName().equals("prepareStatement")&&a[0] instanceof String sql&&value instanceof PreparedStatement statement){var params=new HashMap<Integer,Object>();return proxy(statement,PreparedStatement.class,(s,sm,sa)->{
    if(sm.getName().startsWith("set")&&sa!=null&&sa.length>=2&&sa[0] instanceof Integer index)params.put(index,sa[1]);
    if(armed&&Thread.currentThread()==thread&&sm.getName().equals("executeQuery")&&sql.contains("FROM meeting ")&&params.containsValue(meeting)&&StackWalker.getInstance().walk(frames->frames.anyMatch(f->f.getClassName().equals("ama.transcript.MinutesGraphDiscovery")&&f.getMethodName().equals("select")))){
     check(actual.getAutoCommit()&&!TransactionSynchronizationManager.isActualTransactionActive(),"Actual pre-D metadata boundary must be root-free");discoveries++;
     if(mode.equals("CUMULATIVE")){armed=false;check(renewal.call(),"Genuine queue heartbeat must renew the same actual lease");renewals++;}
     else if(discoveries==1){long begin=System.nanoTime();if(mode.equals("DEADLINE"))Thread.sleep(12000);check(renewal.call(),"Actual coverage renewal required");renewals++;pauses.add(System.nanoTime()-begin);}
     else if(discoveries==2){armed=false;long begin=System.nanoTime();if(mode.equals("DEADLINE")){long end=LocalCoverageChargeTrace.observedDeadline()+TimeUnit.MILLISECONDS.toNanos(100);while(System.nanoTime()<end)Thread.sleep(20);}else Thread.currentThread().interrupt();pauses.add(System.nanoTime()-begin);}
     else throw new IllegalStateException("Bounded control probe must not enter a third discovery");
    }
    return invoke(statement,sm,sa);
   });}return value;
  });}
  public Connection getConnection()throws SQLException{return wrap(delegate.getConnection());}public Connection getConnection(String user,String password)throws SQLException{return wrap(delegate.getConnection(user,password));}
 }
 static TranscriptAcquisitionBudget.Ledger ledger(Object prepared)throws Exception{var method=prepared.getClass().getDeclaredMethod("budget");method.setAccessible(true);return(TranscriptAcquisitionBudget.Ledger)method.invoke(prepared);}
 public static void main(String[] args)throws Exception{
  check("1".equals(System.getenv("AMA_LOCAL_DEV"))&&(args.length==3||args.length==4),"Explicit owned coverage-budget qualification required");Path file=Path.of(args[0]).toRealPath(),output=Path.of(args[2]).toRealPath();check(file.getParent().endsWith(Path.of(".tools/local-app"))&&output.startsWith(file.getParent().resolve("coverage-budget")),"Fresh owned evidence required");var p=new Properties();try(var in=Files.newInputStream(file)){p.load(in);}String url=p.getProperty("database.url");check(url.matches("jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/ama_local_dev\\?.+"),"Exact owned daily DB required");var fixture=new ObjectMapper().readTree(Files.readString(Path.of(args[1])));String meeting=fixture.get("meetingId").asText(),task=fixture.get("taskId").asText();UUID.fromString(meeting);UUID.fromString(task);
  var env=new StandardEnvironment();env.getPropertySources().addFirst(new PropertiesPropertySource("daily",p));var source=new Source(ControlledMinutesDataSource.create(url,p.getProperty("database.user"),p.getProperty("database.password")),meeting);var jdbc=new JdbcTemplate(source);jdbc.setQueryTimeout(5);var configured=ConfiguredProcessing.read(env);
  try(var definitions=ConfiguredBackends.read(env);var client=ConfiguredPublication.read(env,configured.read(),configured.index()).client()){
   var catalog=new FileBackendCatalog(source,definitions.backends(),definitions.defaultId());catalog.configure();var runtime=LocalAcquisitionBudgetCheck.build(source,env,catalog,client);var actor=new Actor("dev-owner",Status.ACTIVE,Set.of(Role.USER));var lease=runtime.queue().claim("MINUTES_GENERATE","LOCAL_COVERAGE_"+output.getFileName()).orElseThrow();check(lease.taskId().equals(task)&&lease.attempt()==1,"Exact fresh actual task lease required");var before=LocalMeetingInfoRollbackCheck.snapshot(jdbc,meeting);var heartbeat=Executors.newSingleThreadScheduledExecutor();
   source.renewal=()->heartbeat.submit(()->runtime.queue().renew(lease)).get(20,TimeUnit.SECONDS);
   try{
    var settings=ConfiguredMinutes.read(env,configured.read(),configured.index());var preparation=settings.preparation(runtime.processing().components().authority());source.mode=args.length==4?args[3]:"CUMULATIVE";
    if(!source.mode.equals("CUMULATIVE")){
     check(Set.of("DEADLINE","CANCEL").contains(source.mode),"Known observation mode required");var report=new LinkedHashMap<String,Object>();source.armed=true;source.started=System.nanoTime();var renewed=new AtomicInteger();var scheduled=heartbeat.scheduleAtFixedRate(()->{if(runtime.queue().renew(lease))renewed.incrementAndGet();},3,3,TimeUnit.SECONDS);MinutesContracts.FailureCode code=null;
     try{LocalCoverageChargeTrace.run(()->preparation.prepareStored(actor,lease),report::putAll);throw new IllegalStateException("Original bound must reject");}catch(MinutesContracts.Failure failure){code=failure.code();}finally{Thread.interrupted();source.armed=false;scheduled.cancel(false);}
     long elapsed=System.nanoTime()-source.started;check(code==(source.mode.equals("DEADLINE")?MinutesContracts.FailureCode.BUDGET_EXCEEDED:MinutesContracts.FailureCode.CANCELLED),"Original budget/cancellation failure required");check(source.discoveries==2,"First coverage must be discarded before second fresh D");check(((Number)report.get("distinctChargedLedgerReferences")).intValue()==1,"Exactly one original actual ledger reference required");if(source.mode.equals("DEADLINE")){check(source.pauses.stream().allMatch(n->n<TimeUnit.SECONDS.toNanos(30)),"Each local D remains inside its own 30-second bound");check(elapsed>=TimeUnit.SECONDS.toNanos(30),"Actual original operation deadline must elapse without clock mutation");}
     check(before.equals(LocalMeetingInfoRollbackCheck.snapshot(jdbc,meeting)),"Control rejection must not change business graph");check(jdbc.queryForObject("SELECT COUNT(*) FROM external_execution WHERE task_id=?",Long.class,task)==0&&jdbc.queryForObject("SELECT COUNT(*) FROM generation_candidate WHERE task_id=?",Long.class,task)==0,"No external execution/candidate");report.put("mode",source.mode);report.put("taskId",task);report.put("meetingId",meeting);report.put("discoveries",source.discoveries);report.put("singlePublicPrepareStoredCall",true);report.put("originalFailureCode",code.name());report.put("actualElapsedMillis",TimeUnit.NANOSECONDS.toMillis(elapsed));report.put("localDiscoveryPauseMillis",source.pauses.stream().map(TimeUnit.NANOSECONDS::toMillis).toList());report.put("actualPeriodicHeartbeats",renewed.get());report.put("zeroBusinessChangeExecutionCandidate",true);report.put("pass",true);Files.writeString(output.resolve("report.json"),new ObjectMapper().writeValueAsString(report));System.out.println(new ObjectMapper().writeValueAsString(report));return;
    }
    source.armed=true;var result=LocalCoverageChargeTrace.run(()->preparation.prepareStored(actor,lease));var charges=result.charges();
    var report=new LinkedHashMap<String,Object>();report.put("meetingId",meeting);report.put("taskId",task);report.put("genuineFactoriesQueueAndPreparer",true);report.put("entryExitOnlyInstrumentation",true);report.put("initialTraceForcedQueueRenewals",source.renewals);report.put("chargeCalls",charges.size());report.put("sameLedger",charges.size()>=2&&charges.stream().map(x->x.get("ledgerIdentity")).distinct().count()==1);report.put("charges",charges);
    boolean retained=source.renewals==1&&charges.size()==2&&Boolean.TRUE.equals(report.get("sameLedger"));
    if(retained){
     var usage=ledger(result.prepared()).usage();long cap=result.peakCopyByteAdmission()-1;check(cap>=usage[3]&&cap>0,"Native peak acquisition admission must include transient JDBC buffering");report.put("nativeTwoRoundCopyBytes",usage[3]);report.put("nativePeakCopyByteAdmission",result.peakCopyByteAdmission());Files.writeString(output.resolve("trace.json"),new ObjectMapper().writeValueAsString(report));env.getPropertySources().addFirst(new MapPropertySource("qualification-copy-cap",Map.of("minutes.bounds.copy-bytes",Long.toString(cap))));var tight=ConfiguredMinutes.read(env,configured.read(),configured.index()).preparation(runtime.processing().components().authority());
     check(source.renewal.call(),"Baseline current same-owner lease renewal required");source.armed=false;tight.prepareStored(actor,lease);boolean rejected=false;check(source.renewal.call(),"Boundary current same-owner lease renewal required");source.armed=true;
     try{tight.prepareStored(actor,lease);}catch(MinutesContracts.Failure failure){check(failure.code()==MinutesContracts.FailureCode.BUDGET_EXCEEDED,"Only actual cumulative budget denial qualifies");rejected=true;}
     report.put("configuredCopyByteCap",cap);report.put("totalForcedCoverageRenewals",source.renewals);report.put("baselineSingleRoundFits",true);report.put("failedCoverageRoundRetainedAtBudgetBoundary",rejected);retained&=rejected;
    }
    check(before.equals(LocalMeetingInfoRollbackCheck.snapshot(jdbc,meeting)),"Read-only preparation must not change business graph/receipt/audit/outbox");check(jdbc.queryForObject("SELECT COUNT(*) FROM external_execution WHERE task_id=?",Long.class,task)==0&&jdbc.queryForObject("SELECT COUNT(*) FROM generation_candidate WHERE task_id=?",Long.class,task)==0,"No external execution or candidate may be created by preparation qualification");report.put("zeroExternalExecutionAndCandidate",true);report.put("pass",retained);Files.writeString(output.resolve("report.json"),new ObjectMapper().writeValueAsString(report));System.out.println(new ObjectMapper().writeValueAsString(report));check(retained,"Both completed D acquisitions must be charged before any coverage recapture");
   }finally{source.armed=false;heartbeat.shutdownNow();heartbeat.awaitTermination(5,TimeUnit.SECONDS);}
  }
 }
}
